'  float bowl = -(1.0 - smoothstep(0.0, 1.0, d));',
'  float pan  = -smoothstep(1.00, 0.84, d);',
'  float base = mix(bowl, pan, big)*0.92;',
'  float rim  = exp(-(d-0.94)*(d-0.94)*26.0)*1.12;',
'  float terr = exp(-(d-0.79)*(d-0.79)*210.0)*0.24*big;',
'  float peak = exp(-d*d*30.0)*0.62*smoothstep(0.33, 0.46, rad);',
'  float ejec = exp(-(d-1.42)*(d-1.42)*2.6)*0.135;',
'  return (base + rim + terr + peak + ejec)*(0.34 + 0.66*age);',
'}',
'float craterCell(vec2 p, vec2 period, float cl, float seed){',
'  vec2 i = floor(p), f = fract(p);',
'  vec2 sq = vec2(cl, 1.0);',
'  float acc = 0.0;',
'  for(int y=-1;y<=1;y++){',
'    for(int x=-1;x<=1;x++){',
'      vec2 g = vec2(float(x),float(y));',
'      vec4 h = hash4(mod(i + g, period) + seed);',
'      vec2 c = g + 0.16 + 0.68*h.xy;',
'      float rad = 0.13 + 0.34*h.z*h.z;',
'      acc += craterProfile(length((f-c)*sq)/(rad*cl), rad, h.w);',
'    }',
'  }',
'  return acc;',
'}',
