      x, y,
      vx:.18+rnd()*.8+edge*.35,
      vy:(rnd()-.5)*.8,
      size:.55+rnd()*1.35,
      life:620+rnd()*520,
      maxLife:1140,
      phase:rnd()*Math.PI*2,
      spin:rnd()>.5 ? 1 : -1,
