      const i = (py*w+px)*4;
      const alpha = pixels[i+3];
      if(alpha < 34 || rnd() > .34) continue;

      const x = (x0+px)/dpr;
      const y = (y0+py)/dpr;
      const dx = x-V.pointer.x, dy = y-V.pointer.y;
      const dist = Math.hypot(dx,dy);
      if(dist > radius || dist < radius*.16) continue;

      const nx = dx/Math.max(1,dist);
      const ny = dy/Math.max(1,dist);
      const burst = .35+rnd()*1.35;
      const tangent = (rnd()-.5)*1.4;
