        x, y,
        vx:nx*burst-ny*tangent+(rnd()-.5)*.35,
        vy:ny*burst+nx*tangent-.15+rnd()*.55,
        size:.65+rnd()*1.55,
        life:560+rnd()*620,
        maxLife:1180,
        phase:rnd()*Math.PI*2,
        spin:rnd()>.5 ? 1 : -1,
        color:pixels[i] + ',' + pixels[i+1] + ',' + pixels[i+2],
