    V.canvas.parentElement.dataset.suctionState = suctionActive ? 'active' : 'idle';
    V.canvas.parentElement.dataset.particles = V.particles.length;
    V.canvas.parentElement.dataset.dissolveStrength = V.dissolve.toFixed(2);
    V.canvas.parentElement.dataset.fieldTilt = V.tilt.y.toFixed(2);
