  RIM_LIGHT: 0.85,
  TILT_Z: -0.17, TILT_X: 0.11, TILT_Y: 0.0,  /* axis tilt */
  SPIN: 0.0455,                             /* rad/s — one turn in ~2m20s */
  LON0: 8,                                  /* longitude facing the camera at t=0 */

