    blurMat.uniforms.uDir.value.set(1 / mips[i].w, 0);
    pass(blurMat, mips[i].b);
    blurMat.uniforms.tD.value = mips[i].b.texture;
    blurMat.uniforms.uDir.value.set(0, 1 / mips[i].h);
    pass(blurMat, mips[i].a);
