'}',
'float ripple(vec2 p, float t){',
'  float sum = 0.;',
'  for(int i = 0; i < 3; i++){',
'    if(uRip[i].w < 0.5) continue;',
'    float age = t - uRip[i].z;',
'    if(age < 0. || age > 4.) continue;',
