/* ─────────────── sizing ─────────────── */
/* mip levels are chosen so a level always covers the same number of CSS px,
   whatever the device pixel ratio */
const DPR_STEP = Math.round(Math.log2(Math.min(window.devicePixelRatio || 1, 2)));
const MIPS = Math.round(CFG.mips) + DPR_STEP;
