  camera.left = -w/2; camera.right = w/2; camera.top = h/2; camera.bottom = -h/2;
  camera.updateProjectionMatrix();

  /* the composition is authored at 1440×1026 — scale the rig with the frame */
  const s = Math.max(0.5, Math.min(1.9, Math.hypot(w, h) / Math.hypot(1440, 1026)));
  U.uScale.value  = s;
  U.uWaist.value  = h * CFG.waist;
  U.uYTop.value   =  h * (0.5 + CFG.spanTop);
  U.uYBot.value   = -h * (0.5 + CFG.spanBottom);
