  addEventListener('pointermove',function(e){
    pointer.x=(e.clientX/innerWidth)*2-1;
    pointer.y=(e.clientY/innerHeight)*2-1;
    pHoverTarget=1;
  },{passive:true});
  addEventListener('pointerleave',function(){ pHoverTarget=0; });
  addEventListener('pointerup',function(e){ if(e.pointerType!=='mouse') pHoverTarget=0; });
