  _e.set(orbEl, orbAz, 0, 'YXZ'); _q.setFromEuler(_e);
  camera.position.copy(CAM_OFF).applyQuaternion(_q).add(PIVOT);
  camera.quaternion.copy(_q).multiply(BASE_Q);
