  // the star field and the strand band are carried by the pointer, not by a clock
  var rollT = REDUCED ? 0 : -pointer.x * pHover * CTL.pointerOrbit;
  starRoll   += (rollT*0.085 - starRoll)   * ek;
  strandRoll += (rollT*0.55  - strandRoll) * ek;
  skyUniforms.uStarRot.value=starRoll;
  if(strands) strands.material.uniforms.uSpin.value=strandRoll;

  // The card holds its pose until the pointer turns it; only the float is its own.
  // (the pose was solved in a +Z-forward frame, so both angles flip for three.js)
  card.rotation.x=-(CARD_RX + orbEl/ORB_EL*CARD_TILT_X);
  card.rotation.y=-(CARD_RY - orbAz/ORB_AZ*CARD_TILT_Y);
  card.position.y=CARD_Y+0.0042*CTL.floatMotion*Math.sin(OMEGA*t*0.34+2.44);
  card.position.x=CARD_X+0.0026*CTL.floatMotion*Math.sin(OMEGA*t*0.29+0.51);

  // specular band sweep (measured: 1.5 s sinusoid across the card face)

  camera.updateMatrixWorld();
  cardUniforms.uCam.value.setFromMatrixPosition(camera.matrixWorld);
  for(var si=0;si<SUBJECT_UNIFORMS.length;si++) SUBJECT_UNIFORMS[si].uCam.value.copy(cardUniforms.uCam.value);
  haloUniforms.uCam.value.copy(cardUniforms.uCam.value);
  glowMat.uniforms.uCam.value.copy(cardUniforms.uCam.value);
  if(strands) strands.material.uniforms.uTime.value=t;
  waterUniforms.uCam.value.copy(cardUniforms.uCam.value);

  // ---- reflection pass ----
  reflCam.matrixWorld.multiplyMatrices(MIRROR,camera.matrixWorld);
  reflCam.matrixWorldInverse.copy(reflCam.matrixWorld).invert();
  reflCam.projectionMatrix.copy(camera.projectionMatrix);
  reflCam.projectionMatrixInverse.copy(camera.projectionMatrixInverse);
